create table if not exists admin_recipient_delete_logs(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references campaigns(id) on delete cascade,admin_user_id uuid not null references auth.users(id),affected_count int not null,restored_available int not null,reason text not null,deleted_records jsonb not null default '[]'::jsonb,created_at timestamptz not null default now());
alter table admin_recipient_delete_logs enable row level security;revoke all on admin_recipient_delete_logs from anon,authenticated;
create index if not exists idx_recipient_delete_logs_campaign_created on admin_recipient_delete_logs(campaign_id,created_at desc);

create or replace function admin_delete_recipients(p_campaign text,p_spin_ids uuid[],p_reason text,p_admin_user uuid,p_confirmation text) returns jsonb language plpgsql security definer set search_path=public as $$declare c campaigns;ids uuid[];participant_ids uuid[];snapshot jsonb;affected int;restored int;new_version bigint;begin if p_confirmation<>'DELETE RECIPIENTS' then raise exception 'CONFIRMATION_REQUIRED';end if;if char_length(trim(p_reason))<3 then raise exception 'REASON_REQUIRED';end if;if coalesce(array_length(p_spin_ids,1),0)<1 then raise exception 'SELECTION_REQUIRED';end if;if array_length(p_spin_ids,1)>100 then raise exception 'SELECTION_LIMIT';end if;if not exists(select 1 from admin_users where user_id=p_admin_user)then raise exception 'ADMIN_FORBIDDEN';end if;select * into c from campaigns where code=p_campaign for update;if not found then raise exception 'CAMPAIGN_NOT_FOUND';end if;select array_agg(s.id),array_agg(distinct s.participant_id),jsonb_agg(jsonb_build_object('spin_id',s.id,'participant_id',s.participant_id,'participant_name',pt.name,'phone',pt.phone,'prize_id',s.prize_id,'prize_name',p.name,'prize_unit_id',s.prize_unit_id,'status',s.status,'created_at',s.created_at)) into ids,participant_ids,snapshot from spins s join participants pt on pt.id=s.participant_id join prizes p on p.id=s.prize_id where s.campaign_id=c.id and s.id=any(p_spin_ids) for update of s;if coalesce(array_length(ids,1),0)<>coalesce(array_length(p_spin_ids,1),0)then raise exception 'SPIN_SELECTION_INVALID';end if;update prize_units set status='AVAILABLE',awarded_at=null,participant_id=null,spin_id=null where campaign_id=c.id and spin_id=any(ids);get diagnostics restored=row_count;delete from spins where id=any(ids);get diagnostics affected=row_count;delete from participants pt where pt.id=any(participant_ids)and not exists(select 1 from spins s where s.participant_id=pt.id);update campaigns set inventory_version=inventory_version+1 where id=c.id returning inventory_version into new_version;insert into admin_recipient_delete_logs(campaign_id,admin_user_id,affected_count,restored_available,reason,deleted_records)values(c.id,p_admin_user,affected,restored,trim(p_reason),coalesce(snapshot,'[]'::jsonb));return jsonb_build_object('ok',true,'affected',affected,'restored_available',restored,'inventory_version',new_version);end$$;
revoke all on function admin_delete_recipients(text,uuid[],text,uuid,text) from public,anon,authenticated;grant execute on function admin_delete_recipients(text,uuid[],text,uuid,text) to service_role;
